(564967, 57612, 9073, '<td valign="top">nice take on the challenge theme. Maybe the lighting could have been better to avoid those ugly shadows to the right of the pieces. 5</td>', 'nice take on the challenge theme. Maybe the lighting could have been better to avoid those ugly shadows to the right of the pieces. 5', '2004-02-02 01:21:02.000000', NULL, 1),
(564968, 57705, 8054, '<td valign="top">Good concept for the challenge. Entry has good detail and sharp focus. However, I would like to see more contrast and if the image was more symmetrical I would rate it higher.</td>', 'Good concept for the challenge. Entry has good detail and sharp focus. However, I would like to see more contrast and if the image was more symmetrical I would rate it higher.', '2004-02-02 01:22:24.000000', NULL, 1),
(564969, 57723, 16052, '<td valign="top">I thought about doing peas and carrots for this one and now I am glad I didn''t as your composition is by far much more interesting.  Carrots are a bit red, peas are perfect.</td>', 'I thought about doing peas and carrots for this one and now I am glad I didn''t as your composition is by far much more interesting.  Carrots are a bit red, peas are perfect.', '2004-02-02 01:22:41.000000', NULL, 1),
(564970, 58197, 9073, '<td valign="top">As a joke photo, this is fine. Maybe it''d have been better if the fish were coming in from a side, rather than be positioned dead centre. The background does not have very vibrant colours, nor is the fish particularly sharp.  4</td>', 'As a joke photo, this is fine. Maybe it''d have been better if the fish were coming in from a side, rather than be positioned dead centre. The background does not have very vibrant colours, nor is the fish particularly sharp.  4', '2004-02-02 01:23:36.000000', NULL, 1),
