(564977, 58205, 15959, '<td valign="top">love the picture, especially the red gloves...I am giving this a 10, but your title threw me off</td>', 'love the picture, especially the red gloves...I am giving this a 10, but your title threw me off', '2004-02-02 01:26:28.000000', NULL, 1),
