(565053, 58178, 16188, '<td valign="top">Nice idea, though the yin seems to be winning... :)</td>', 'Nice idea, though the yin seems to be winning... :)', '2004-02-02 02:13:03.000000', NULL, 1),
(565054, 57564, 9073, '<td valign="top">Your subject is fine, and you''ve filled the frame well. I just wish that the ice were more clear and maybe some action - like actually pouring the soda in, or showing the enjoyment of the drink. 5</td>', 'Your subject is fine, and you''ve filled the frame well. I just wish that the ice were more clear and maybe some action - like actually pouring the soda in, or showing the enjoyment of the drink. 5', '2004-02-02 02:14:04.000000', NULL, 1),
(565055, 58203, 14499, '<td valign="top">Don''t swear!  ;)    Nice.. I like the angles just a bit over cropped perhaps?</td>', 'Don''t swear!  ;)    Nice.. I like the angles just a bit over cropped perhaps?', '2004-02-02 02:15:01.000000', NULL, 1),
(565056, 57792, 9073, '<td valign="top">I can see where you''re going with this one. This is how I feel every time I plan a DPC entry. You''re brave. 7</td>', 'I can see where you''re going with this one. This is how I feel every time I plan a DPC entry. You''re brave. 7', '2004-02-02 02:15:26.000000', NULL, 1),
