(566475, 57893, 16493, '<td valign="top">nice touch in the post editing.</td>', 'nice touch in the post editing.', '2004-02-03 03:42:28.000000', NULL, 1),
(566481, 57613, 16493, '<td valign="top">nice background and forground - but the middle is lacking a bit of detail.</td>', 'nice background and forground - but the middle is lacking a bit of detail.', '2004-02-03 03:46:56.000000', NULL, 1),
