(566683, 57728, 10170, '<td valign="top">Nicely done, the unusual crop really works well.  Great lips.</td>', 'Nicely done, the unusual crop really works well.  Great lips.', '2004-02-03 07:20:52.000000', NULL, 1),
(566684, 57893, 10170, '<td valign="top">Excellent use of desaturation.  Love it.</td>', 'Excellent use of desaturation.  Love it.', '2004-02-03 07:21:36.000000', NULL, 1),
(566714, 58182, 16493, '<td valign="top">Nice setup of the gun and amo. frame and target bit destracting.</td>', 'Nice setup of the gun and amo. frame and target bit destracting.', '2004-02-03 08:03:19.000000', NULL, 1),
(566715, 57939, 16493, '<td valign="top">I think it looks better with just the jing jang and not the salt and pepper shakers.</td>', 'I think it looks better with just the jing jang and not the salt and pepper shakers.', '2004-02-03 08:04:35.000000', NULL, 1),
(566716, 57905, 16493, '<td valign="top">Good idea - don''t like to have the subject too centerd though.</td>', 'Good idea - don''t like to have the subject too centerd though.', '2004-02-03 08:06:05.000000', NULL, 1),
(566717, 57421, 15137, '<td valign="top">A perfect pair</td>', 'A perfect pair', '2004-02-03 08:07:19.000000', NULL, 1),
(566719, 57746, 15137, '<td valign="top">Nice photo, scary subject</td>', 'Nice photo, scary subject', '2004-02-03 08:08:02.000000', NULL, 1),
