(567016, 58110, 14773, '<td valign="top">great capture</td>', 'great capture', '2004-02-03 13:31:05.000000', NULL, 1),
(567018, 58040, 12061, '<td valign="top">i love the clarity of this photo and how the brush blends yet contrasts nicely with the hair. Nice touch on blurring the border, it works well to add to the overall impact of the photograph. Great shot! 8</td>', 'i love the clarity of this photo and how the brush blends yet contrasts nicely with the hair. Nice touch on blurring the border, it works well to add to the overall impact of the photograph. Great shot! 8', '2004-02-03 13:32:28.000000', NULL, 1),
