(567300, 57612, 15407, '<td valign="top">Another photo that Nails the theme.  I like the colors &amp; detail in your shot yet the other shots also works very well without color and very soft detail... I''ll have to vote both of them HIGH.</td>', 'Another photo that Nails the theme.  I like the colors & detail in your shot yet the other shots also works very well without color and very soft detail... I''ll have to vote both of them HIGH.', '2004-02-03 18:47:04.000000', NULL, 1),
(567305, 57402, 15407, '<td valign="top">Toning down the "Hot Spot" on the gilt at the top of the cup would garner another point from me.</td>', 'Toning down the "Hot Spot" on the gilt at the top of the cup would garner another point from me.', '2004-02-03 18:52:07.000000', NULL, 1),
