(568621, 57881, 11241, '<td valign="top">Is this a photo of you?  Great DOF and the way the face is so soft looking</td>', 'Is this a photo of you?  Great DOF and the way the face is so soft looking', '2004-02-04 13:48:02.000000', NULL, 1),
