(570029, 57896, 12802, '<td valign="top">Nice, seems a little bit out of focus, playing with it in PS it looks a little clearer.  Nice lighting, maybe a bit more on the left hand side?  Good shot! 8</td>', 'Nice, seems a little bit out of focus, playing with it in PS it looks a little clearer.  Nice lighting, maybe a bit more on the left hand side?  Good shot! 8', '2004-02-05 15:24:08.000000', NULL, 1),
(570033, 57920, 12802, '<td valign="top">Cheeky... :-)<br/> <br/>Seems a little out of focus, nice take on the challenge!  Good lighting 8</td>', 'Cheeky... :-) Seems a little out of focus, nice take on the challenge!  Good lighting 8', '2004-02-05 15:26:22.000000', NULL, 1),
(570035, 57941, 12802, '<td valign="top">I like this idea, different...<br/> <br/>You could have played about with the Hue/Saturation to make the colours a bit brighter though.  8</td>', 'I like this idea, different... You could have played about with the Hue/Saturation to make the colours a bit brighter though.  8', '2004-02-05 15:28:33.000000', NULL, 1),
(570040, 57760, 12802, '<td valign="top">Very nice, good use of negative space. Also, not putting your subject in the centre works well.  Seems a tiny wee bit bright, but I do really like this!  10</td>', 'Very nice, good use of negative space. Also, not putting your subject in the centre works well.  Seems a tiny wee bit bright, but I do really like this!  10', '2004-02-05 15:30:54.000000', NULL, 1),
(570044, 57920, 3102, '<td valign="top">God Bless America!  :)</td>', 'God Bless America!  :)', '2004-02-05 15:35:35.000000', NULL, 1),
(570049, 57995, 12802, '<td valign="top">Nice!  Good choice for the challenge.  Good DOF (Maybe an idea for the DOF Challenge...) and nice lighting setup. Maybe a tiny bit sharper would be nice (IMO) to bring out a wee bit more detail in the needle and the beginning of the thread.<br/> <br/>I would have liked the reel to have been a bit closer, or a shade more in focus.  The wee white spot/mark on the blue thread is a little offputting.  Good shot though!  8</td>', 'Nice!  Good choice for the challenge.  Good DOF (Maybe an idea for the DOF Challenge...) and nice lighting setup. Maybe a tiny bit sharper would be nice (IMO) to bring out a wee bit more detail in the needle and the beginning of the thread. I would have liked the reel to have been a bit closer, or a shade more in focus.  The wee white spot/mark on the blue thread is a little offputting.  Good shot though!  8', '2004-02-05 15:37:51.000000', NULL, 1),
(570100, 58124, 11895, '<td valign="top">I think I''d like this better in color, well composed and proper exposure, gave me a chuckle</td>', 'I think I''d like this better in color, well composed and proper exposure, gave me a chuckle', '2004-02-05 16:37:12.000000', NULL, 1),
(570103, 57943, 11895, '<td valign="top">beautiful picture but doesn''t fit "two things that go together" IMHO</td>', 'beautiful picture but doesn''t fit "two things that go together" IMHO', '2004-02-05 16:44:05.000000', NULL, 1),
(570106, 57751, 11895, '<td valign="top">good idea but way over-exposed, or manipulated too much; the glass is lost against the background and there is not much detail in the cat''s fur</td>', 'good idea but way over-exposed, or manipulated too much; the glass is lost against the background and there is not much detail in the cat''s fur', '2004-02-05 16:47:11.000000', NULL, 1),
(570122, 58106, 11895, '<td valign="top">yummy, makes my mouth water, but haven''t we seen that crooked legged martini glass before in a couple of other challenges?</td>', 'yummy, makes my mouth water, but haven''t we seen that crooked legged martini glass before in a couple of other challenges?', '2004-02-05 17:24:49.000000', NULL, 1),
(570125, 57751, 811, '<td valign="top">I love this shot.  It is a great capture.  The color contrast is beautiful as is the lighting and focus.  This is one of those that makes me say, "I wish I had done that!"  Hope to see it in the top three!</td>', 'I love this shot.  It is a great capture.  The color contrast is beautiful as is the lighting and focus.  This is one of those that makes me say, "I wish I had done that!"  Hope to see it in the top three!', '2004-02-05 17:28:14.000000', NULL, 1),
(570126, 57791, 811, '<td valign="top">The clarity and simplicity of htis shot works well. Much better full size than thumbnail.  Good work.</td>', 'The clarity and simplicity of htis shot works well. Much better full size than thumbnail.  Good work.', '2004-02-05 17:28:55.000000', NULL, 1),
(570127, 57807, 811, '<td valign="top">I like the metaphorical approach you have taken.  Very nice.</td>', 'I like the metaphorical approach you have taken.  Very nice.', '2004-02-05 17:29:22.000000', NULL, 1),
(570128, 57612, 811, '<td valign="top">I like the composition and color in this shot.  Not sure I really like the background color, but I don''t know what might have worked better.</td>', 'I like the composition and color in this shot.  Not sure I really like the background color, but I don''t know what might have worked better.', '2004-02-05 17:30:29.000000', NULL, 1),
(570130, 57921, 811, '<td valign="top">That was my pose exactly for about 5 years!!  How well I remember, and how right you are. <br/>Good shot.</td>', 'That was my pose exactly for about 5 years!!  How well I remember, and how right you are. Good shot.', '2004-02-05 17:31:17.000000', NULL, 1),
(570132, 58148, 811, '<td valign="top">I like the simplicity of htis and you have done an excellent job of capturing the detail in the thread.  It really adds to the shot, I think.</td>', 'I like the simplicity of htis and you have done an excellent job of capturing the detail in the thread.  It really adds to the shot, I think.', '2004-02-05 17:31:57.000000', NULL, 1),
(570133, 58182, 811, '<td valign="top">Great work at keeping lighting glares to a minimum.</td>', 'Great work at keeping lighting glares to a minimum.', '2004-02-05 17:32:28.000000', NULL, 1),
(570142, 58013, 811, '<td valign="top">They do go together, and the color contrast has the potential of being nice.  However, the overall focus is a little soft and it kinda gives the impression of mushy veggies, and the light glares are a little bright, especially at the top of the pic.</td>', 'They do go together, and the color contrast has the potential of being nice.  However, the overall focus is a little soft and it kinda gives the impression of mushy veggies, and the light glares are a little bright, especially at the top of the pic.', '2004-02-05 17:38:17.000000', NULL, 1),
(570144, 57490, 811, '<td valign="top">I like the idea and setup, but the background is a bit distracting.  Maybe a tighter crop and a different color cast would help (though the yellowish tone does give the feeling of old photography)</td>', 'I like the idea and setup, but the background is a bit distracting.  Maybe a tighter crop and a different color cast would help (though the yellowish tone does give the feeling of old photography)', '2004-02-05 17:39:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(570150, 57944, 811, '<td valign="top">A lot of details seems to be lost in the duck -- its eye is very noticeable, almost to the point of being distracting.  Did you use a polarizer?  I think, if not, it might help cut down on the glare of the water, adn give it a little more color "tone"</td>', 'A lot of details seems to be lost in the duck -- its eye is very noticeable, almost to the point of being distracting.  Did you use a polarizer?  I think, if not, it might help cut down on the glare of the water, adn give it a little more color "tone"', '2004-02-05 17:43:08.000000', NULL, 1),
(570153, 57642, 811, '<td valign="top">The light on the salt shaker is such that it looks almost as much like pepper as the pepper does.  A couple of suggestions -- get closer to your subject and lower your perspective.  That would help to fill the frame more and add to the interest of the shot.</td>', 'The light on the salt shaker is such that it looks almost as much like pepper as the pepper does.  A couple of suggestions -- get closer to your subject and lower your perspective.  That would help to fill the frame more and add to the interest of the shot.', '2004-02-05 17:48:32.000000', NULL, 1),
(570181, 58145, 11793, '<td valign="top">interesting...</td>', 'interesting...', '2004-02-05 18:19:54.000000', NULL, 1),
