(570418, 57417, 2891, '<td valign="top">I am making an assumption here that you took out the background digitally.  If that is the case, try shooting on colored cardboard or paper.  The edges on the outside need some work.  If I am assuming wrong, I apologise.  I am giving a rating between the two.</td>', 'I am making an assumption here that you took out the background digitally.  If that is the case, try shooting on colored cardboard or paper.  The edges on the outside need some work.  If I am assuming wrong, I apologise.  I am giving a rating between the two.', '2004-02-05 22:26:37.000000', NULL, 1),
(570420, 57728, 2891, '<td valign="top">Great idea, but I find the lips distracting.</td>', 'Great idea, but I find the lips distracting.', '2004-02-05 22:30:02.000000', NULL, 1),
(570426, 58060, 2891, '<td valign="top">Good beer, but goes better with pretzles, unsalted. ;)</td>', 'Good beer, but goes better with pretzles, unsalted. ;)', '2004-02-05 22:42:00.000000', NULL, 1),
(570463, 57875, 12160, '<td valign="top">I like this a lot, very moody and has a distinct character about it. Not postcard pretty yet very moving. The colors and the darkness are very effective.</td>', 'I like this a lot, very moody and has a distinct character about it. Not postcard pretty yet very moving. The colors and the darkness are very effective.', '2004-02-06 00:23:52.000000', NULL, 1),
(570473, 57807, 12160, '<td valign="top">Very well done. The technical aspects all work together for a great photo. The creativity makes it a very moving and emotive portrait. High marks for both. 10</td>', 'Very well done. The technical aspects all work together for a great photo. The creativity makes it a very moving and emotive portrait. High marks for both. 10', '2004-02-06 00:31:20.000000', NULL, 1),
(570493, 57721, 11895, '<td valign="top">good idea but too bright, these items are floating in air, tone down the brightness until there is a little detail or texture in the background, even some shadow would help anchor them</td>', 'good idea but too bright, these items are floating in air, tone down the brightness until there is a little detail or texture in the background, even some shadow would help anchor them', '2004-02-06 00:45:32.000000', NULL, 1),
